import React, { useState } from "react";

import Navbar from "../../components/Navbar";
import Sidebar from "../../components/Sidebar";
import { Container, Card, Form, Button, Alert } from "react-bootstrap";

import { calculateEMI, totalRepayment, totalInterest } from "../../utils/calculators";

function EmiCalculator() {

    const [principal, setPrincipal] = useState("");
    const [rate, setRate] = useState("");
    const [months, setMonths] = useState("");
    const [emi, setEmi] = useState("");
    const [repayment, setRepayment] = useState("");
    const [interest, setInterest] = useState("");

    const calculate = () => {
        const emiValue = calculateEMI(
            parseFloat(principal),
            parseFloat(rate),
            parseInt(months)
        );

        const total = totalRepayment(emiValue, months);
        const totalInt = totalInterest(principal, total);

        setEmi(emiValue);
        setRepayment(total);
        setInterest(totalInt);
    };

    return (
        <div>
            <Navbar />

            <div className="d-flex">
                <Sidebar />

                <Container className="p-4">
                    <Card className="border-0 shadow-sm nb-shadow-soft">
                        <Card.Header className="bg-white fw-bold">
                            EMI Calculator
                        </Card.Header>

                        <Card.Body>
                            <Form.Group className="mb-3">
                                <Form.Label>Loan Amount</Form.Label>
                                <Form.Control
                                    type="number"
                                    value={principal}
                                    onChange={(e) => setPrincipal(e.target.value)}
                                />
                            </Form.Group>

                            <Form.Group className="mb-3">
                                <Form.Label>Interest Rate %</Form.Label>
                                <Form.Control
                                    type="number"
                                    value={rate}
                                    onChange={(e) => setRate(e.target.value)}
                                />
                            </Form.Group>

                            <Form.Group className="mb-3">
                                <Form.Label>Tenure Months</Form.Label>
                                <Form.Control
                                    type="number"
                                    value={months}
                                    onChange={(e) => setMonths(e.target.value)}
                                />
                            </Form.Group>

                            <Button variant="success" className="rounded-pill" onClick={calculate}>
                                Calculate EMI
                            </Button>

                            {emi && (
                                <Alert variant="success" className="mt-4">
                                    <h5>Monthly EMI : ₹{emi}</h5>
                                    <h5>Total Repayment : ₹{repayment}</h5>
                                    <h5>Total Interest : ₹{interest}</h5>
                                </Alert>
                            )}
                        </Card.Body>
                    </Card>
                </Container>
            </div>
        </div>
    );
}

export default EmiCalculator;
